CREATE TABLE "library_image_jobs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
	"workspace_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"idempotency_key" text NOT NULL,
	"request_hash" text NOT NULL,
	"request" jsonb NOT NULL,
	"plan" jsonb NOT NULL,
	"status" text DEFAULT 'queued' NOT NULL,
	"estimated_cost_cents" integer NOT NULL,
	"actual_cost_cents" integer,
	"provider_submitted" boolean DEFAULT false NOT NULL,
	"attempt_count" integer DEFAULT 0 NOT NULL,
	"trigger_run_id" text,
	"provider_request_id" text,
	"usage" jsonb,
	"safe_error_message" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "library_image_jobs_state" CHECK ("status" in ('queued','running','succeeded','failed')),
	CONSTRAINT "library_image_jobs_cost" CHECK ("estimated_cost_cents">0 and ("actual_cost_cents" is null or "actual_cost_cents">=0) and "attempt_count" between 0 and 1)
);
